69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    private final IdentityKeyResolver identityKeyResolver;
101	
102	    private final HouseholdResolver householdResolver;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 AddressNormalizer addressNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 IdentityKeyResolver identityKeyResolver,
112	                                 HouseholdResolver householdResolver) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.emailNormalizer = emailNormalizer;
120	        this.identityKeyResolver = identityKeyResolver;
121	        this.householdResolver = householdResolver;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        owners.forEach(this::populateHouseholdMemberCount);
137	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
138	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        populateHouseholdMemberCount(owner);
149	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
154	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
155	     * by the mapper alone.
156	     *
157	     * @param owner the owner to map
158	     * @return the owner DTO carrying its identity key
159	     */
160	    private OwnerDto toOwnerDto(Owner owner) {
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
163	        return ownerDto;
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        normalizeAndValidate(ownerFieldsDto);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        populateDerivedFields(owner, ownerFieldsDto);
174	        requireUniqueIdentity(owner);
175	        flagPossibleDuplicate(owner);
176	        this.clinicService.saveOwner(owner);
177	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
178	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
179	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
180	        populateHouseholdMemberCount(owner);
181	        OwnerDto ownerDto = toOwnerDto(owner);
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    /**
188	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
189	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
190	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
191	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
192	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
193	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), backfilling any existing household members
194	     * that lack it, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The owner is
195	     * mutated in place; the caller applies the duplicate guard and saves it.
196	     *
197	     * @param owner          the newly mapped owner about to be saved
198	     * @param ownerFieldsDto the incoming owner payload
199	     */
200	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
201	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
202	        owner.setNamesakeCount(countNamesakes(owner));
203	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
204	        assignHouseholdId(owner, ownerFieldsDto);
205	    }
206	
207	    /**
208	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
209	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
210	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
211	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
212	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
213	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
214	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
215	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
216	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
217	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
218	     * assigned (see {@link #requireUniqueIdentity}).
219	     *
220	     * @param ownerFieldsDto the incoming owner payload, mutated in place
221	     * @throws MissingOwnerFieldsException if any required field is missing or blank
222	     */
223	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
224	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
225	        validateRequiredFields(ownerFieldsDto);
226	        validatePostcode(ownerFieldsDto);
227	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
228	        ownerFieldsDto.setTelephone(telephone);
229	        requireCityHasCapacity(ownerFieldsDto.getCity());
230	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
231	        ownerFieldsDto.setRegistrationDate(registrationDate);
232	        requireDailyLimitNotReached(registrationDate);
233	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
234	        ownerFieldsDto.setEmail(email);
235	    }
236	
237	    /**
238	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
239	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
240	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
241	     * later than the current server date is rejected.
242	     *
243	     * @param ownerFieldsDto the incoming owner payload
244	     * @return the effective registration date rolled forward onto a business day
245	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
246	     */
247	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
248	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
249	        if (effective == null) {
250	            effective = LocalDate.now();
251	        }
252	        else if (effective.isAfter(LocalDate.now())) {
253	            throw new FutureRegistrationDateException(
254	                "the registration date must not be later than the current server date");
255	        }
256	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
257	            effective = effective.plusDays(1);
258	        }
259	        return effective;
260	    }
261	
262	    /**
263	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
264	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
265	     * further owner may be created for that day.
266	     *
267	     * @param registrationDate the adjusted business-day registration date of the owner being created
268	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
269	     */
270	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
271	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
272	            throw new DailyOwnerLimitExceededException(
273	                "the maximum number of owners for today has already been reached");
274	        }
275	    }
276	
277	    /**
278	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
279	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
280	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
281	     * warning threshold) so both express the same per-day count in one place.
282	     *
283	     * @param registrationDate the adjusted business-day registration date to count owners for
284	     * @return the number of existing owners registered on that day
285	     */
286	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
287	        return this.clinicService.findAllOwners().stream()
288	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
289	            .count();
290	    }
291	
292	    /**
293	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
294	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
295	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
296	     * reflects only owners that predate it.
297	     *
298	     * @param registrationDate the adjusted business-day registration date of the owner being created
299	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
300	     */
301	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
302	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
303	    }
304	
305	    /**
306	     * Counts how many existing owners already share the given owner's first and last name, compared
307	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
308	     * create; it is zero when the owner's name is unique.
309	     *
310	     * @param owner the newly mapped owner about to be saved
311	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
312	     */
313	    private int countNamesakes(Owner owner) {
314	        String firstName = owner.getFirstName();
315	        String lastName = owner.getLastName();
316	        return (int) this.clinicService.findAllOwners().stream()
317	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
318	                && lastName.equalsIgnoreCase(existing.getLastName()))
319	            .count();
320	    }
321	
322	    /**
323	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
324	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
325	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
326	     *
327	     * @param ownerFieldsDto the owner payload to validate
328	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
329	     */
330	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
331	        List<String> missingFields = new ArrayList<>();
332	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
333	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
334	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
335	        requireText(missingFields, "city", ownerFieldsDto.getCity());
336	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
337	        if (!missingFields.isEmpty()) {
338	            throw new MissingOwnerFieldsException(missingFields);
339	        }
340	    }
341	
342	    private void requireText(List<String> missingFields, String fieldName, String value) {
343	        if (value == null || value.isBlank()) {
344	            missingFields.add(fieldName);
345	        }
346	    }
347	
348	    /**
349	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
350	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
351	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
352	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
353	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
354	     *
355	     * @param ownerFieldsDto the incoming owner payload
356	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
357	     */
358	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
359	        String postcode = ownerFieldsDto.getPostcode();
360	        if (postcode == null) {
361	            return;
362	        }
363	        Region region = Region.forCity(ownerFieldsDto.getCity());
364	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
365	            throw new InvalidPostcodeException(
366	                "postcode " + postcode + " is not valid for the city's region " + region.name());
367	        }
368	    }
369	
370	    /**
371	     * Rejects creating an owner whose whole derived {@code identityKey} (see
372	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
373	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
374	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
375	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
376	     *
377	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
378	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
379	     */
380	    private void requireUniqueIdentity(Owner owner) {
381	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
382	        boolean inUse = this.clinicService.findAllOwners().stream()
383	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
384	        if (inUse) {
385	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
386	        }
387	    }
388	
389	    /**
390	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
391	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. It is a
392	     * possible duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode
393	     * but carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true}
394	     * and {@code possibleDuplicateOf} to that existing owner's id (the first match in
395	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
396	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
397	     *
398	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
399	     */
400	    private void flagPossibleDuplicate(Owner owner) {
401	        owner.setPossibleDuplicate(false);
402	        String postcode = owner.getPostcode();
403	        if (postcode == null || postcode.isBlank()) {
404	            return;
405	        }
406	        String lastName = owner.getLastName();
407	        String telephone = owner.getTelephone();
408	        for (Owner existing : this.clinicService.findAllOwners()) {
409	            if (lastName.equalsIgnoreCase(existing.getLastName())
410	                && postcode.equals(existing.getPostcode())
411	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
412	                owner.setPossibleDuplicate(true);
413	                owner.setPossibleDuplicateOf(existing.getId());
414	                return;
415	            }
416	        }
417	    }
418	
419	    /**
420	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
421	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
422	     *
423	     * @param city the city of the owner being created
424	     * @throws OwnerCityFullException if the city already contains 50 or more owners
425	     */
426	    private void requireCityHasCapacity(String city) {
427	        long cityOwners = this.clinicService.findAllOwners().stream()
428	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
429	            .count();
430	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
431	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
432	        }
433	    }
434	
435	    /**
436	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
437	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
438	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
439	     * incidental formatting differences and abbreviation variants do not affect membership.
440	     *
441	     * @param ownerFieldsDto the incoming owner payload
442	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
443	     *         them; empty when none match
444	     */
445	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
446	        String lastName = householdResolver.collapseWhitespace(ownerFieldsDto.getLastName());
447	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
448	        return this.clinicService.findAllOwners().stream()
449	            .filter(existing -> householdResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
450	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
451	            .toList();
452	    }
453	
454	    /**
455	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
456	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
457	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
458	     * identifier itself is computed by {@link #computeHouseholdId}, so every member of the same household resolves to
459	     * the same stable value regardless of creation order. Existing members that predate the feature and still lack the
460	     * identifier are backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
461	     *
462	     * @param owner          the newly mapped owner about to be saved
463	     * @param ownerFieldsDto the incoming owner payload
464	     */
465	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
466	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
467	            return;
468	        }
469	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
470	        if (members.isEmpty()) {
471	            return;
472	        }
473	        String householdId = computeHouseholdId(ownerFieldsDto);
474	        owner.setHouseholdId(householdId);
475	        backfillHouseholdMembers(householdId, members);
476	    }
477	
478	    /**
479	     * Computes the shared {@code householdId} for an owner payload. The identifier is derived deterministically (see
480	     * {@link HouseholdResolver#deriveHouseholdId}), so it is a pure function of the payload's household-identifying
481	     * fields and every member of the same household resolves to the same stable value regardless of creation order.
482	     * Computing it is kept separate from deciding whether to assign it (see {@link #assignHouseholdId}).
483	     *
484	     * @param ownerFieldsDto the incoming owner payload
485	     * @return the shared household identifier for the payload
486	     */
487	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
488	        return householdResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
489	    }
490	
491	    /**
492	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
493	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
494	     * into line so the whole household shares the single value; members that already carry it are left untouched.
495	     *
496	     * @param householdId the shared household identifier
497	     * @param members     the existing owners in the household
498	     */
499	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
500	        for (Owner member : members) {
501	            if (!householdId.equals(member.getHouseholdId())) {
502	                member.setHouseholdId(householdId);
503	                this.clinicService.saveOwner(member);
504	            }
505	        }
506	    }
507	
508	    /**
509	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
510	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
511	     * household is counted as a household of one.
512	     *
513	     * @param owner the owner whose household size should be resolved
514	     */
515	    private void populateHouseholdMemberCount(Owner owner) {
516	        String householdId = owner.getHouseholdId();
517	        if (householdId == null) {
518	            owner.setHouseholdMemberCount(1);
519	            return;
520	        }
521	        long members = this.clinicService.findAllOwners().stream()
522	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
523	            .count();
524	        owner.setHouseholdMemberCount((int) members);
525	    }
526	
527	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
528	    @Override
529	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
530	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
531	        if (currentOwner == null) {
532	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
533	        }
534	        validatePostcode(ownerFieldsDto);
535	        currentOwner.setAddress(ownerFieldsDto.getAddress());
536	        currentOwner.setCity(ownerFieldsDto.getCity());
537	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
538	        currentOwner.setLastName(ownerFieldsDto.getLastName());
539	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
540	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
541	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
542	        this.clinicService.saveOwner(currentOwner);
543	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
544	    }
545	
546	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
547	    @Transactional
548	    @Override
549	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
550	        Owner owner = this.clinicService.findOwnerById(ownerId);
551	        if (owner == null) {
552	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
553	        }
554	        this.clinicService.deleteOwner(owner);
555	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
556	    }
557	
558	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
559	    @Override
560	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
561	        Owner owner = this.clinicService.findOwnerById(ownerId);
562	        if (owner == null) {
563	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
564	        }
565	        HttpHeaders headers = new HttpHeaders();
566	        Pet pet = petMapper.toPet(petFieldsDto);
567	        owner.setId(ownerId);
568	        pet.setOwner(owner);
569	        pet.getType().setName(null);
570	        this.clinicService.savePet(pet);
571	        PetDto petDto = petMapper.toPetDto(pet);
572	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
573	            .buildAndExpand(pet.getId()).toUri());
574	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
575	    }
576	
577	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
578	    @Override
579	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
580	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
581	        if (currentOwner != null) {
582	            Pet currentPet = this.clinicService.findPetById(petId);
583	            if (currentPet != null) {
584	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
585	                currentPet.setName(petFieldsDto.getName());
586	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
587	                this.clinicService.savePet(currentPet);
588	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
589	            }
590	        }
591	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
592	    }
593	
594	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
595	    @Override
596	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
597	        HttpHeaders headers = new HttpHeaders();
598	        Visit visit = visitMapper.toVisit(visitFieldsDto);
599	        Pet pet = new Pet();
600	        pet.setId(petId);
601	        visit.setPet(pet);
602	        this.clinicService.saveVisit(visit);
603	        VisitDto visitDto = visitMapper.toVisitDto(visit);
604	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
605	            .buildAndExpand(visit.getId()).toUri());
606	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
607	    }
608	
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
613	        Owner owner = this.clinicService.findOwnerById(ownerId);
614	        if (owner != null) {
615	            Pet pet = owner.getPet(petId);
616	            if (pet != null) {
617	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
618	            }
619	        }
620	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
621	    }
622	}
