1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
5	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Derives the owner-identity values matching keys off: the owner's {@code customerCode} and the single
10	 * {@code identityKey} that all duplicate detection is expressed through. The shared household id lives alongside in
11	 * {@link HouseholdResolver}; this resolver folds that id into the identity key but does not derive it. Keeping this
12	 * here (rather than in {@link OwnerMapper} or the REST controller) mirrors {@link HouseholdResolver},
13	 * {@link LocalityResolver} and {@link MembershipLevelResolver} and gives owner-identity derivation a single home.
14	 * Unlike the static utilities it collaborates with the field normalizers, so it is a Spring component.
15	 */
16	@Component
17	public class IdentityKeyResolver {
18	
19	    private final TelephoneNormalizer telephoneNormalizer;
20	
21	    private final EmailNormalizer emailNormalizer;
22	
23	    public IdentityKeyResolver(TelephoneNormalizer telephoneNormalizer,
24	                               EmailNormalizer emailNormalizer) {
25	        this.telephoneNormalizer = telephoneNormalizer;
26	        this.emailNormalizer = emailNormalizer;
27	    }
28	
29	    /**
30	     * Derives the owner's {@code identityKey}, the single value all duplicate detection is expressed through. It is
31	     * formatted {@code <normalizedTelephone>|<email or empty>|<householdId or empty>}, joining the canonical E.164
32	     * telephone (see {@link TelephoneNormalizer#canonicalize}), the normalized email (see
